import { CodeViewer, type CodeViewerCopyDetail } from '@absoluteui/components/code-viewer';

const host = document.createElement('div');
document.body.append(host);
CodeViewer.create(host, {
  label: 'Leave request handler',
  filename: 'leave.ts',
  language: 'typescript',
  code: "export async function requestLeave(days: number): Promise<void> {\n  if (days <= 0) throw new Error('days must be positive');\n  await submit({ days });\n}\n",
  highlightLines: [2],
});
host.addEventListener('aui-copy', (event) => {
  host.dataset.copied = String((event as CustomEvent<CodeViewerCopyDetail>).detail.text.length);
});

import { CodeViewer, type CodeViewerChangeDetail } from '@absoluteui/components/code-viewer';

const host = document.createElement('div');
document.body.append(host);
const viewer = CodeViewer.create(host, {
  label: 'Policy changes',
  language: 'json',
  diff: {
    original: '{\n  "annualLeave": 20,\n  "carryOver": 5\n}',
    modified: '{\n  "annualLeave": 22,\n  "carryOver": 5,\n  "sabbatical": true\n}',
    mode: 'split',
  },
});
host.addEventListener('aui-change', (event) => {
  host.dataset.mode = (event as CustomEvent<CodeViewerChangeDetail>).detail.mode ?? '';
});
viewer.scrollToLine(3);

import { diffLines } from '@absoluteui/components/code-viewer';

const changes = diffLines('a\nb\nc', 'a\nx\nc');
const summary = changes.filter((line) => line.op !== 'equal').map((line) => `${line.op} ${line.text}`);
document.body.dataset.changes = summary.join(', ');
